Queries.MCSLOG_SECS_LOG:
[
	{
		$match: {
			"TIME_EX": { $gte: ISODate(#{From}), $lte: ISODate(#{To}) },
			"LEVEL": { $in: [ #{Level} ] },
			$expr: { $gt: [ { $concat: [ { $dateToString: { date: "$TIME_EX", format: "%Y%m%d%H%M%S%L" } }, { $toString: "$_id" } ] }, #{Key} ] },
			"HOST": { $in: [ #{Host} ] },
			
				
					$and: [
						{ "SECSII": #{Secs} },
						{ "TEXT": /${Text}/ },
					]
				
				
					$or: [
						{ "SECSII": #{Secs} },
						{ "TEXT": /${Text}/ },
					]
				
			
		}
	},
	{ $sort: { "TIME_EX": 1 } },
	{ $limit: ${Limit} },
	{
		$set: {
			"Key": { $concat: [ { $dateToString: { date: "$TIME_EX", format: "%Y%m%d%H%M%S%L" } }, { $toString: "$_id" } ] },
			"TIME_EX": { $ifNull: [ { $dateToString: { date: "$TIME_EX", format: "%Y-%m-%d %H:%M:%S.%L", timezone: "Asia/Seoul" } }, "" ] },
			"SECSII": { $ifNull: ["$SECSII", ""] },
			"LEVEL": { $ifNull: ["$LEVEL", ""] },
			"S/F": { $ifNull: ["$S/F", ""] },
			"SB": { $ifNull: ["$SB", ""] },
			"NAME": { $ifNull: ["$NAME", ""] },
			"DATA": { $ifNull: ["$DATA", ""] },
			"CEID_TYPE": { $ifNull: ["$CEID_TYPE", ""] },
			"TEXT": { $ifNull: ["$TEXT", ""] },
			"SKEY": { $ifNull: ["$SKEY", ""] },
			"HOST": { $ifNull: ["$HOST", ""] },
			"_table": #{Collection}
		}
	}
]

Queries.MCSLOG_RAW_LOG:
[
	
	
		{
			$set: {
				"TAG_PARSED": { $regexFind: { input: "$tag", "regex": /^(\w+).(\w+).(\w+)/ } },
				"CLASS_REG": { $regexFind: { input: "$line", "regex": /\[*\s*kr.co.aim.nanotrans.([A-Za-z0-9_\-. ]*)\]*/ } },
				"XML_REG": { $regexFind: { input: "$line", "regex": /\s+\-\s+\[*(?:<\?xml version="1.0" encoding="UTF-8"\?>)?(.*)\]*/, "options": "s" } },
			}
		},
		{
			$project: {
				"_id": 1,
				"TIME_EX": 1,
				"FAB": { $toUpper: { $trim: { input: { $arrayElemAt: [ "$TAG_PARSED.captures", 0 ] } } } },
				"LOG": { $toUpper: { $trim: { input: { $arrayElemAt: [ "$TAG_PARSED.captures", 2 ] } } } },
				"LEVEL": "$level",
				"THREAD": "$thread",
				"CLASS": { $trim: { input: { $arrayElemAt: [ "$CLASS_REG.captures", 0 ] } } },
				"TEXT": "$line",
				"HOST": { $trim: { input: { $arrayElemAt: [ "$TAG_PARSED.captures", 1 ] } } },
				"PROCESS": { "$toLower": { "$substr": [ "$filename", { "$subtract": [{ "$indexOfCP": [ "$filename", ".log" ]}, 4]}, 4]}},
				"TEXT_XML": { $trim: { input: { $arrayElemAt: [ "$XML_REG.captures", 0 ] } } },
			}
		},
	
	
	{
		$match: {
			"TIME_EX": { $gte: ISODate(#{From}), $lte: ISODate(#{To}) },
			"LEVEL": { $in: [ #{Level} ] },
			$expr: { $gt: [ { $concat: [ { $dateToString: { date: "$TIME_EX", format: "%Y%m%d%H%M%S%L" } }, { $toString: "$_id" } ] }, #{Key} ] },
			"HOST": { $in: [ #{Host} ] },
			"PROCESS": #{Process},
			"TEXT": /${Text}/,
		}
	},
	{ $limit: ${Limit} },
	{
		$set: {
			"Key": { $concat: [ { $dateToString: { date: "$TIME_EX", format: "%Y%m%d%H%M%S%L" } }, { $toString: "$_id" } ] },
			"TIME_EX": { $ifNull: [ { $dateToString: { date: "$TIME_EX", format: "%Y-%m-%d %H:%M:%S.%L", timezone: "Asia/Seoul" } }, "" ] },
			"FAB": { $ifNull: ["$FAB", ""] },
			"LOG": { $ifNull: ["$LOG", ""] },
			"LEVEL": { $ifNull: ["$LEVEL", ""] },
			"THREAD": { $ifNull: ["$THREAD", ""] },
			"CLASS": { $ifNull: ["$CLASS", ""] },
			"TEXT": { $ifNull: ["$TEXT", ""] },
			"HOST": { $ifNull: ["$HOST", ""] },
			"PROCESS": { $ifNull: ["$PROCESS", ""] },
			"TEXT_XML": { $ifNull: ["$TEXT_XML", ""] },
			"_table": #{Collection}
		}
	}
]

