Queries.MCSLOG_TRANSPORT_RETURN_LOG:
[ { $match: { "TIME_EX": { $gte: ISODate(#{From}), $lte: ISODate(#{To}) }, "method": "createTransportJobHistory", $expr: { $gt: [ { $concat: [ { $dateToString: { date: "$TIME_EX", format: "%Y%m%d%H%M%S%L" } }, { $toString: "$_id" } ] }, #{Key} ] }, $text: { $search: #{FullText} }, "SOURCEMACHINETYPE": { $in: [ #{MachineTypesSource} ] }, "DESTMACHINETYPE": { $in: [ #{MachineTypesDest} ] }, "SOURCEMACHINENAME": { $in: [ #{MachineNamesSource} ] }, "DESTMACHINENAME": { $in: [ #{MachineNamesDest} ] }, "CARRIER": #{CarrierName}, "LOTID": #{LotID}, "TRANSPORTJOBID": #{TransportJobID}, "TRANSPORTCOMMANDID": #{TransportCommandID},
"STATE": { $in: [ "COMPLETED", "CANCELED" ] },
} }, { $sort: { "TIME_EX" : 1 } }, { $set: { "Key": { $concat: [ { $dateToString: { date: "$TIME_EX", format: "%Y%m%d%H%M%S%L" } }, { $toString: "$_id" } ] }, "TIME_EX": { $ifNull: [ { $dateToString: { date: "$TIME_EX", format: "%Y-%m-%d %H:%M:%S.%L", timezone: "Asia/Seoul" } }, "" ] }, "TRANS_JOBSTART": { $ifNull: [ { $dateToString: { date: "$TRANS_JOBSTART", format: "%Y-%m-%d %H:%M:%S.%L", timezone: "Asia/Seoul" } }, "" ] }, "TRANS_JOBEND": { $ifNull: [ { $dateToString: { date: "$TRANS_JOBEND", format: "%Y-%m-%d %H:%M:%S.%L", timezone: "Asia/Seoul" } }, "" ] }, "TRANSPORTJOBID": { $ifNull: [ "$TRANSPORTJOBID", "" ] }, "STATE": { $ifNull: [ "$STATE", "" ] }, "CARRIER": { $ifNull: [ "$CARRIER", "" ] }, "SOURCEMACHINENAME": { $ifNull: [ "$SOURCEMACHINENAME", "" ] }, "SOURCEMACHINETYPE": { $ifNull: [ "$SOURCEMACHINETYPE", "" ] }, "SOURCEUNITNAME": { $ifNull: [ "$SOURCEUNITNAME", "" ] }, "DESTTYPE": { $ifNull: [ "$DESTTYPE", "" ] }, "DESTMACHINENAME": { $ifNull: [ "$DESTMACHINENAME", "" ] }, "DESTMACHINETYPE": { $ifNull: [ "$DESTMACHINETYPE", "" ] }, "DESTUNITNAME": { $ifNull: [ "$DESTUNITNAME", "" ] }, "REASON": { $ifNull: [ "$REASON", "" ] }, "FIXEDROUTE": { $ifNull: [ "$FIXEDROUTE", "" ] }, "PRIORITY": { $ifNull: [ "$PRIORITY", "" ] }, "LOTID": { $ifNull: [ "$LOTID", "" ] }, "BATCHID": { $ifNull: [ "$BATCHID", "" ] }, "STEPID": { $ifNull: [ "$STEPID", "" ] }, "PROCESSID": { $ifNull: [ "$PROCESSID", "" ] }, "DESCRIPTION": { $ifNull: [ "$DESCRIPTION", "" ] }, "CREATEUSER": { $ifNull: [ "$CREATEUSER", "" ] }, "BATCHTYPE": { $ifNull: [ "$BATCHTYPE", "" ] }, "TRANSPORTCOMMANDID": { $ifNull: [ "$TRANSPORTCOMMANDID", "" ] }, "TRANSPORTMACHINENAME": { $ifNull: [ "$TRANSPORTMACHINENAME", "" ] }, "TRANSPORTTYPE": { $ifNull: [ "$TRANSPORTTYPE", "" ] }, "TRANSPORTUNITNAME": { $ifNull: [ "$TRANSPORTUNITNAME", "" ] }, "_table": #{Collection} } } ]

Queries.MCSLOG_TRANSPORT_COMPLETED_CARRIER_FROM_:
[
	{
		$match: {
			"TIME_EX": { $gte: ISODate(#{From}), $lte: ISODate(#{To}) },
			$expr: { $gt: [ { $concat: [ { $dateToString: { date: "$TIME_EX", format: "%Y%m%d%H%M%S%L" } }, { $toString: "$_id" } ] }, #{Key} ] },
			$text: { $search: #{FullText} },
			"MACHINETYPE": { $in: [ #{MachineTypes} ] },
			"MACHINENAME": { $in: [ #{MachineNames} ] },
			"CARRIER": #{CarrierName},
		}
	},
	{ $sort: { "TIME_EX" : 1 } },
	{
		$set: {
			"Key": { $concat: [ { $dateToString: { date: "$TIME_EX", format: "%Y%m%d%H%M%S%L" } }, { $toString: "$_id" } ] },
			"TIME_EX": { $ifNull: [ { $dateToString: { date: "$TIME_EX", format: "%Y-%m-%d %H:%M:%S.%L", timezone: "Asia/Seoul" } }, "" ] },
			"FROM": { $ifNull: [ { $dateToString: { date: "$START_TIME", format: "%Y%m%d%H%M%S", timezone: "Asia/Seoul" } }, "" ] },
			"TO": { $ifNull: [ { $dateToString: { date: "$TIME_EX", format: "%Y%m%d%H%M%S", timezone: "Asia/Seoul" } }, "" ] },
			"CARRIER": { $ifNull: [ "$CARRIER", "" ] },
			"LOCATION_ID": { $ifNull: [ "$LOCATION_ID", "" ] },
			"TOTAL_ELAPSED": { $divide: [ { $toDouble: { $ifNull: [ "$ELAPSED_MSEC" , "0" ] } }, 1000 ] },
			"MACHINENAME": { $ifNull: [ "$MACHINENAME", "" ] },
			"MACHINETYPE": { $ifNull: [ "$MACHINETYPE", "" ] },
			"_table": #{Collection}
		}
	}
]
